import json

with open('artifacts/updated_empirical_results.json') as f:
    data = json.load(f)

# Look at bias structure
humaid_configs = [c for c in data['confusion_matrices'] if c.startswith('humaid_')]

# Collect per-topology bias for HumAID 
for topo in ['iv', 'exposure', 'confounding', 'mediation', 'collider', 'mbias', 'frontdoor']:
    biases = []
    for config in humaid_configs:
        if config in data['biases'] and topo in data['biases'][config]:
            b = data['biases'][config][topo]
            if isinstance(b, dict):
                # might have abs_bias_pct or similar
                biases.append(b)
            else:
                biases.append(b)
    if biases:
        if isinstance(biases[0], dict):
            abs_pcts = [b.get('abs_bias_pct', b.get('abs_relative_bias', 0)) for b in biases]
            print(f'{topo}: abs_bias_pct range = {min(abs_pcts)*100:.1f}%--{max(abs_pcts)*100:.1f}%')
        else:
            print(f'{topo}: {biases}')
    else:
        print(f'{topo}: no data')
" 2>&1
